function aics_sheet_key(string $v): string { return strtoupper(trim(preg_replace('/[^A-Z0-9]+/','_', $v), '_')); }
function aics_sheet_date($v): ?string {
    $v=trim((string)$v); if($v==='') return null;
    if(is_numeric($v) && (float)$v>20000 && (float)$v<70000) return gmdate('Y-m-d',((int)$v-25569)*86400);
    foreach(['Y-m-d','m/d/Y','n/j/Y','m-d-Y','M d, Y','F d, Y','d/m/Y'] as $f){$d=DateTime::createFromFormat($f,$v);if($d instanceof DateTime)return $d->format('Y-m-d');}
    $t=strtotime($v);return $t!==false?date('Y-m-d',$t):null;
}
function aics_sheet_num($v): float { $v=str_replace([',','₱','PHP',' '],'',(string)$v); return is_numeric($v)?(float)$v:0.0; }
function aics_sheet_rows(string $path, string $ext): array {
