      $xml=$z->getFromName('xl/worksheets/sheet1.xml');$z->close();if($xml===false)throw new RuntimeException('The first worksheet could not be read.');$sx=simplexml_load_string($xml);if(!$sx)throw new RuntimeException('The worksheet XML is invalid.');$grid=[];foreach($sx->sheetData->row as $row){$vals=[];foreach($row->c as $cell){$ref=(string)$cell['r'];preg_match('/^([A-Z]+)/',$ref,$m);$col=0;foreach(str_split($m[1]??'A') as $ch)$col=$col*26+ord($ch)-64;$v=(string)$cell->v;if((string)$cell['t']==='s')$v=$strings[(int)$v]??'';elseif((string)$cell['t']==='inlineStr')$v=implode('',array_map('strval',$cell->is->t));$vals[$col-1]=$v;}if($vals){ksort($vals);$grid[]=array_values($vals);}}if(!$grid)throw new RuntimeException('The first worksheet contains no rows.');$head=array_map(fn($v)=>aics_sheet_key((string)$v),array_shift($grid));$out=[];$n=1;foreach($grid as $line){$r=[];foreach($head as $i=>$k)$r[$k]=$line[$i]??'';if(array_filter($r,fn($v)=>trim((string)$v)!=='')){$r['_row']=++$n;$out[]=$r;}}return $out;
    }
    throw new RuntimeException('Please upload an .xlsx or .csv file.');
}
