        $backupDir=__DIR__.'/backups';if(!is_dir($backupDir)&&!mkdir($backupDir,0775,true)&&!is_dir($backupDir))throw new RuntimeException('Unable to create database backup folder.');$backup=$backupDir.'/AICS-before-import-'.date('Ymd-His').'.sql';$tables=$pdo->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);$dump="-- AICS backup before sheet import\n-- ".date('c')."\nSET FOREIGN_KEY_CHECKS=0;\n";foreach($tables as $t){$qt='`'.str_replace('`','``',$t).'`';$create=$pdo->query('SHOW CREATE TABLE '.$qt)->fetch(PDO::FETCH_NUM);if(!$create)continue;$dump.="DROP TABLE IF EXISTS {$qt};\n{$create[1]};\n";$st=$pdo->query('SELECT * FROM '.$qt);while($row=$st->fetch(PDO::FETCH_ASSOC)){$cols=array_map(fn($k)=>'`'.str_replace('`','``',$k).'`',array_keys($row));$vals=array_map(fn($v)=>$v===null?'NULL':$pdo->quote((string)$v),array_values($row));$dump.='INSERT INTO '.$qt.' ('.implode(',',$cols).') VALUES ('.implode(',',$vals).');'."\n";}}$dump.="SET FOREIGN_KEY_CHECKS=1;\n";if(file_put_contents($backup,$dump,LOCK_EX)===false)throw new RuntimeException('Database backup failed; import was not applied.');
